async function json(url){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch(url,{signal:controller.signal});if(!r.ok)throw new Error('lookup');return await r.json()}finally{clearTimeout(timer)}}
